// Reference implementation of the fenced_code preprocessor model, for validation
// against /workspace/dataset/test2_executable.

const TAB = 4;

export function expandtabs(s, size = TAB) {
  let out = '';
  let col = 0;
  for (const ch of s) {
    if (ch === '\t') {
      const n = size - (col % size);
      out += ' '.repeat(n);
      col += n;
    } else if (ch === '\n' || ch === '\r') {
      out += ch;
      col = 0;
    } else {
      out += ch;
      col += 1;
    }
  }
  return out;
}

export function normalize(src) {
  let s = src.replace(//g, '').replace(//g, '');
  s = s.replace(/\r\n/g, '\n').replace(/\r/g, '\n') + '\n\n';
  s = expandtabs(s, TAB);
  // re.sub(r'(?<=\n) +\n', '\n', s)  -- non-overlapping, lookbehind on original
  s = s.replace(/(?<=\n) +\n/g, '\n');
  return s;
}

// ---- attribute-string scanner (markdown.extensions.attr_list.get_attrs) ----
const SCAN = [
  { re: /[^ =]+="[^\n]*?"/y, kind: 'dq' },
  { re: /[^ =]+='[^\n]*?'/y, kind: 'sq' },
  { re: /[^ =]+=[^ =]+/y, kind: 'kv' },
  { re: /[^ =]+/y, kind: 'word' },
  { re: / /y, kind: 'skip' },
];

function pyStrip(s, chars) {
  let a = 0, b = s.length;
  while (a < b && chars.includes(s[a])) a++;
  while (b > a && chars.includes(s[b - 1])) b--;
  return s.slice(a, b);
}

export function getAttrs(str) {
  const out = [];
  let i = 0;
  while (i < str.length) {
    let matched = null;
    for (const p of SCAN) {
      p.re.lastIndex = i;
      const m = p.re.exec(str);
      if (m) { matched = { kind: p.kind, text: m[0], end: p.re.lastIndex }; break; }
    }
    if (!matched || matched.end === i) break;
    const t = matched.text;
    if (matched.kind === 'dq') {
      const idx = t.indexOf('=');
      out.push([t.slice(0, idx), pyStrip(t.slice(idx + 1), '"')]);
    } else if (matched.kind === 'sq') {
      const idx = t.indexOf('=');
      out.push([t.slice(0, idx), pyStrip(t.slice(idx + 1), "'")]);
    } else if (matched.kind === 'kv') {
      const idx = t.indexOf('=');
      out.push([t.slice(0, idx), t.slice(idx + 1)]);
    } else if (matched.kind === 'word') {
      if (t.startsWith('.')) out.push(['.', t.slice(1)]);
      else if (t.startsWith('#')) out.push(['id', t.slice(1)]);
      else out.push([t, t]);
    }
    i = matched.end;
  }
  return out;
}

function parseHlLines(expr) {
  if (!expr) return [];
  const parts = expr.split(/[ \t\n\r\f\v   -     　]+/).filter(x => x.length);
  const out = [];
  for (const p of parts) {
    if (!/^[+-]?\d+$/.test(p)) return [];
    out.push(parseInt(p, 10));
  }
  return out;
}

function parseBoolValue(v) {
  const l = v.toLowerCase();
  if (['true', 'yes', 'y', 'on', '1'].includes(l)) return true;
  if (['false', 'no', 'n', 'off', '0', 'none'].includes(l)) return false;
  return null; // fail_on_errors=False
}

function handleAttrs(attrs) {
  let id = '';
  const classes = [];
  const configs = new Map();
  for (const [k, v] of attrs) {
    if (k === 'id') id = v;
    else if (k === '.') classes.push(v);
    else if (k === 'hl_lines') configs.set(k, parseHlLines(v));
    else if (k === 'use_pygments') configs.set(k, parseBoolValue(v));
    else configs.set(k, v);
  }
  return { id, classes, configs };
}

function esc(t) {
  return t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function pyRepr(v) {
  if (Array.isArray(v)) return '[' + v.join(', ') + ']';
  return String(v);
}

function escAttrib(v) {
  if (Array.isArray(v)) return pyRepr(v); // Python `"&" in list` is False -> no escaping
  return esc(String(v));
}

// ---- fence regex ----
const LANG = '[\\p{L}\\p{N}_#.+\\-]';
const ATTRS = '\\{(?<attrs>(?:[^ =}\\n]+=(?:"[^"\\n]*"|\'[^\'\\n]*\')|[^}\\n])*)\\}';
const FENCE_SRC =
  '(?<fence>^(?:~{3,}|`{3,}))[ ]*' +
  '(?:' + ATTRS + '|' +
  '(?:\\.?(?<lang>' + LANG + '*)[ ]*)?' +
  '(?:hl_lines=(?<quot>"|\')(?<hl>[\\s\\S]*?)\\k<quot>[ ]*)?' +
  ')' +
  '\\n' +
  '(?<code>[\\s\\S]*?)(?<=\\n)' +
  '\\k<fence>[ ]*$';
const FENCE_RE = new RegExp(FENCE_SRC, 'gmu');

export function fencedBlocks(source) {
  // Returns { text, blocks } after preprocessing (blocks in order of extraction)
  let text = normalize(source);
  // preprocessor sees lines joined by \n -- identical to `text`
  const blocks = [];
  let index = 0;
  for (;;) {
    FENCE_RE.lastIndex = index;
    const m = FENCE_RE.exec(text);
    if (!m) break;
    const g = m.groups;
    let lang = null, id = '', classes = [], configs = new Map();
    if (g.attrs !== undefined && g.attrs !== null) {
      const h = handleAttrs(getAttrs(g.attrs));
      id = h.id; classes = h.classes; configs = h.configs;
      if (classes.length) lang = classes.shift();
    } else {
      if (g.lang) lang = g.lang;
      if (g.hl) configs.set('hl_lines', parseHlLines(g.hl));
    }
    let idAttr = '', classAttr = '', langAttr = '', kv = '';
    if (lang) langAttr = ` class="language-${escAttrib(lang)}"`;
    if (classes.length) classAttr = ` class="${escAttrib(classes.join(' '))}"`;
    if (id) idAttr = ` id="${escAttrib(id)}"`;
    const up = configs.has('use_pygments') ? configs.get('use_pygments') : false;
    if (configs.size && !up) {
      for (const [k, v] of configs) {
        if (k === 'use_pygments') continue;
        kv += ` ${k}="${escAttrib(v)}"`;
      }
    }
    const code = esc(g.code);
    const html = `<pre${idAttr}${classAttr}><code${langAttr}${kv}>${code}</code></pre>`;
    blocks.push(html);
    const ph = `wzxhzdk:${blocks.length - 1}`;
    text = text.slice(0, m.index) + '\n' + ph + '\n' + text.slice(m.index + m[0].length);
    index = m.index + ph.length + 2;
  }
  return { text, blocks };
}

