import { fencedBlocks } from './ref.mjs';
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test2_executable';
function run(a) {
  const r = spawnSync(EXE, ['--a', a, '--b', 'x'], { encoding: 'buffer', maxBuffer: 1 << 28 });
  return { out: r.stdout ? r.stdout.toString('utf8') : '', code: r.status };
}

const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));
let ok = 0, mismatch = 0, skipped = 0;
const bad = [];
for (const c of cases) {
  const { text, blocks } = fencedBlocks(c);
  // residual text: replace placeholders, must be all-whitespace for a clean comparison
  let residual = text;
  for (let i = 0; i < blocks.length; i++) residual = residual.split(`wzxhzdk:${i}`).join('');
  const clean = residual.trim() === '';
  const r = run(c);
  if (r.code !== 0) { skipped++; continue; }
  if (clean && blocks.length > 0) {
    const expected = blocks.join('\n') + '\n';
    if (expected === r.out) ok++;
    else { mismatch++; if (bad.length < 25) bad.push({ c, expected, got: r.out }); }
  } else if (blocks.length === 0) {
    // model says: no fence anywhere -> output must not contain <pre><code
    if (!r.out.includes('<pre><code')) ok++;
    else { mismatch++; if (bad.length < 25) bad.push({ c, expected: '(no fence)', got: r.out }); }
  } else {
    // mixed doc: check every block html appears in output
    const allIn = blocks.every(b => r.out.includes(b));
    const count = (r.out.match(/<pre[ >]/g) || []).length;
    if (allIn && count === blocks.length) ok++;
    else { mismatch++; if (bad.length < 25) bad.push({ c, expected: blocks.join(' ||| '), got: r.out }); }
  }
}
console.log(`ok=${ok} mismatch=${mismatch} skipped=${skipped} total=${cases.length}`);
for (const b of bad) {
  console.log('CASE  ' + JSON.stringify(b.c));
  console.log('  EXP ' + JSON.stringify(b.expected));
  console.log('  GOT ' + JSON.stringify(b.got));
}

